    #region Algemene Methods
    /// <summary>Controleer de structuur van de Raw begroting
    /// Geldt voor de element (#) codes 939990, 949990, 960010 en 9861020, gecontroleerd wordt of 
    /// 1) deze codes wel in de begroting maar niet in het begrotingsblad voorkomen
    /// 2) of deze codes onderbouwd zijn (dit is hier niet van toepassing)
    /// </summary>
    /// <param name="begroting">De betreffende begroting</param>
    /// <param name="begrotingBlad">Het bijbehorende begrotingsblad</param>
    /// <param name="context">De context voor eventeuel meldingen</param>
    /// <returns>true indien er geen meldingen zijn, anders false</returns>
    public static bool ControleerStructuur(IBegroting begroting, IBegrotingBlad begrotingBlad, string context)
    {
        List<BRawControle> rawControles = new List<BRawControle>(5);
        for (int teller = 0; teller < 5; teller++)
            rawControles.Add(new BRawControle());

        // Bepaal welke codes als Sub-Hoofdstuk voorkomen in de begroting (939990, 949990, 960010, 960020, 960030)
        for (int stuIndex = begroting._Stu._Aantal - 1; stuIndex > 0; stuIndex--)
        {
            BStructuurRegel stuRegel = begroting._Stu[stuIndex];
            if (stuRegel._Tpe == EOnderbouwing.Element && stuRegel._Niveau == 2) // # regel
            {
                int controlIndex = -1;
                // Het element is onderbouwd als de volgende sturegel dit elementId als parent heeft
                string code = stuRegel._Regel._CclCde;
                switch (code)
                {
                    case RawRegelgeving.c_RawAKCode: controlIndex = 0; break;
                    case RawRegelgeving.c_RawWRCode: controlIndex = 1; break;
                    case RawRegelgeving.c_RawRawBijdrageCode: controlIndex = 2; break;
                    case RawRegelgeving.c_RawFcoBijdrageCode: controlIndex = 3; break;
                    case RawRegelgeving.c_RawVsiBijdrageCode: controlIndex = 4; break;
                }
                if (controlIndex >= 0)
                    rawControles[controlIndex].ZetStatusBgr(code, true, stuIndex);

                // Stop met zoeken als er een elementcode < c_RawAKCode gevonden wordt 
                if (!string.IsNullOrEmpty(code) && string.Compare(code, RawRegelgeving.c_RawAKCode) < 0)
                    break;
            }
        }
        // Bepaal of dezelfde codes ook als % regel of als vast bedrag in het begrotingsblad voorkomen
        foreach (BBegrotingBladSectie sectie in begrotingBlad)
        {
            for (int regelIndex = 0; regelIndex < sectie._Lijst.Count; regelIndex++)
            {
                int controlIndex = -1;
                BBegrotingBladFunctie functie = sectie._Lijst[regelIndex];

                switch (functie._FunctieSoort)
                {
                    case BBegrotingBladFunctie.EFunctieSoort.TotaalOpslagPost:
                    case BBegrotingBladFunctie.EFunctieSoort.TotaalOpslagPostRaw:
                        switch (functie._CclCde)
                        {
                            case RawRegelgeving.c_RawAKCode: controlIndex = 0; break;
                            case RawRegelgeving.c_RawWRCode: controlIndex = 1; break;
                            case RawRegelgeving.c_RawRawBijdrageCode: controlIndex = 2; break;
                            case RawRegelgeving.c_RawFcoBijdrageCode: controlIndex = 3; break;
                            case RawRegelgeving.c_RawVsiBijdrageCode: controlIndex = 4; break;
                        }
                        break;
                    case BBegrotingBladFunctie.EFunctieSoort.VastBedrag:
                        switch (functie._CclCde)
                        {
                            case RawRegelgeving.c_RawAKCode: controlIndex = 0; break;
                            case RawRegelgeving.c_RawWRCode: controlIndex = 1; break;
                        }
                        break;
                }
                if (controlIndex >= 0)
                    rawControles[controlIndex].ZetStatusBgrBld(true, functie._CclCde);
            }
        }

        ILogboek logboek = IoC.Resolve<ILogboek>();
        int aantalMeldingen = 0;
        foreach (BRawControle rawControle in rawControles)
        {
            List<string> meldingen = rawControle.GeefMeldingen();
            foreach (string melding in meldingen)
            {
                aantalMeldingen++;
                logboek.Toevoegen(context, rawControle._StuIndex, melding);
            }
        }

        return aantalMeldingen == 0;
    }
    /// <summary>Bepaal het specifieke raw gedeelte tov een normale opslag
    /// </summary>
    /// <param name="grondBedrag"></param>
    /// <returns></returns>
    public double BepaalBijdrage(double grondBedrag, double opslagFactor, string code, ERawPercentages rawPwercentagesInGebruik)
    {
        double rawFact = 0.0;
        double fcoFact = 0.0;
        double vsiFact = 0.0;
        if ((rawPwercentagesInGebruik & ERawPercentages.Raw) != 0)
            rawFact = _RawPercentage / 100;
        if ((rawPwercentagesInGebruik & ERawPercentages.Fco) != 0)
            fcoFact = _FcoPercentage / 100;
        if ((rawPwercentagesInGebruik & ERawPercentages.Vsi) != 0)
            vsiFact = _VsiPercentage / 100;

        m_BijdrageFactor = 1.0 - (rawFact + fcoFact + vsiFact);
        double wde = grondBedrag * opslagFactor;
        if (m_BijdrageFactor < 1.0)   // Kan wel < 0 zijn (bij som raw / fco percentage > 100)
        {
            double max;
            switch (code)
            {
                case RawRegelgeving.c_RawRawBijdrageCode:
                    max = _RawBijdrageMax;
                    break;
                case RawRegelgeving.c_RawFcoBijdrageCode:
                    max = _FcoBijdrageMax;
                    break;
                case RawRegelgeving.c_RawVsiBijdrageCode:
                    max = _VsiBijdrageMax;
                    break;
                default:
                    return wde;
            }
            // de formule is (Totaal / factor) * (percentage / 100)    (opslagFactor is al het percentage / 100
            wde = Math.Min(grondBedrag / m_BijdrageFactor * opslagFactor, max);
        }
        return wde;
    }
    /// <summary>Bereken het subtotaal van een raw begroting
    /// Het subtotaal van een raw begroting is het totaal van alle elementen tot het eerste 9 element
    /// </summary>
    /// <param name="structuur">De structuurlijst van de begroting</param>
    public BXtoKst BerekenSubtotaal(IStructuur structuur)
    {
        bool rawSubtotaalBepaald = false;

        int stuIndex = 0;
        BElement rootElt = (BElement)structuur[0]._Regel;
        BXtoKst xtoRoot = rootElt.GeefXtoKst();
        BXtoKst xtoKst = new BXtoKst(xtoRoot._Vlt, rootElt.Begroting.BegrotingsValuta);

        while (structuur.GeefOnderbouwing(BBegroting.c_RElId, ref stuIndex))
        {
            IBegrotingsRegel bgrRegel = structuur[stuIndex]._Regel;

            switch (bgrRegel._OnderbouwingType)
            {
                case EOnderbouwing.Element:
                    BElement element = (BElement)bgrRegel;
                    if (element._CclCde.StartsWith(RawRegelgeving.c_RawStaartCode))
                    {
                        if (!rawSubtotaalBepaald)
                        {
                            ZetRawSubTotaal(xtoKst[EXto.Bto, EKst.Aks], rootElt.Begroting.BegrotingsValuta);
                            ZetRawAltSubTotaal(new BBedrag(rootElt.Begroting._VttId, m_RawAltSubtotaal), rootElt.Begroting.BegrotingsValuta);
                            rawSubtotaalBepaald = true;
                            break;
                        }
                    }
                    xtoKst.Optellen(element.GeefBedragen());
                    break;

                case EOnderbouwing.Kostenpost:
                    BKostenpost kostenpost = (BKostenpost)bgrRegel;
                    if (kostenpost._Actief)
                        xtoKst.Optellen(kostenpost.GeefBedragen());
                    break;

                case EOnderbouwing.Opslagpost:
                    BOpslagpost opslagpost = (BOpslagpost)bgrRegel;
                    if (opslagpost._Actief)
                    {
                        for (EKst kst = EKst.Arb; kst <= EKst.Oda; kst++)
                        {
                            xtoKst[(int)EXto.Bto, (int)kst] += opslagpost.GeefBdrKst(kst).Waarde;
                        }
                        xtoKst[(int)EXto.Bto, (int)EKst.Aks] += opslagpost.GeefBdrKst(EKst.Aks).Waarde;
                    }
                    break;
            }

            if (rawSubtotaalBepaald)
                break;
        }
        // Ik ben geen rawSubtotaal tegengekomen >> er is geen staart meer >> bruto en netto zijn gelijk
        if (!rawSubtotaalBepaald)
        {
            ZetRawSubTotaal(xtoKst[EXto.Bto, EKst.Aks], rootElt.Begroting.BegrotingsValuta);
            ZetRawAltSubTotaal(new BBedrag(rootElt.Begroting._VttId, m_RawAltSubtotaal), rootElt.Begroting.BegrotingsValuta);
        }

        return xtoKst;
    }
