    public int GeefAantalDocumentTekstRegels(ETekstType tekstType)
    {
        string? tekst = null;
        switch (tekstType)
        {
            case ETekstType.Voorblad: tekst = m_RawVoorblad; break;
            case ETekstType.Inschrijfbiljet: tekst = m_RawInschrijfBiljet; break;
        }

        int aantalRegels = 0;
        if (!string.IsNullOrEmpty(tekst))
        {
            int index = 0;
            while ((index = tekst.IndexOf(Environment.NewLine, index)) >= 0)
            {
                aantalRegels++;
                index++;
                if (index >= tekst.Length)
                    break;
            }
        }
        return aantalRegels;
    }
