                {
                    bgr.VerwijderBegrotingsRegel(stuIndex, EBgrRegelVerwijderen.Onderbouwing);
                }

                // Stop als we Hoofdstuk "9" / "91" gehad hebben
                ERawBeginStaart type = RawIsBeginRawStaart(stuRegel);
                if (type == ERawBeginStaart.Code9)
                {
                    break;
                }
                if (type == ERawBeginStaart.Code91 && ((rawBeginStaart & ERawBeginStaart.Code9) == 0))
                {
                    break;
                }
            }
        }
    }

