    public static bool ValideerRaw(IBegroting begroting, string context)
    {
        string brutoVerzamelpostLetters = string.Empty;
        double code = -1.0;
        ILogboek logboek = IoC.Resolve<ILogboek>();
        ILogger<BRawInfo> logger = IoC.ResolveLogger<BRawInfo>();
        logboek.Leegmaken();
        logboek.Document = context;
        logboek.ContextView = EViewKey.BegrGridInKlassiekeView;
        int logAantal = logboek.Aantal;
        bool m_91 = false;
        Regex regex = new Regex("\\d{6}");
        int parentid = -1;
        int RawTypes = 0;
        RawJaarversie jaarversie = RawRegelgeving.GetRawJaarversie(begroting._RawInfo._Jaarversie);
        RawContractVorm contractVorm = RawRegelgeving.GetRawContractVorm(begroting._RawInfo._Contractvorm);
        bool hoofdstuk96Aanwezig = false;
        bool elementen96Aanwezig = false;

        #region Controle van gegevens op begrotingsniveau

        // Alleen jaarversie 2010, 2015, 2020 en 2025 verwerken
        if (jaarversie != RawJaarversie.v2010 && jaarversie != RawJaarversie.v2015 && jaarversie != RawJaarversie.v2020 && jaarversie != RawJaarversie.v2025)
        {
            logboek.Toevoegen(begroting._Naam, ProjectResources.TradA0024127269);
        }

        // Alleen contracttypen Bestek, Overeenkomst en Raamovereenkomst verwerken
        switch (contractVorm)
        {
            case RawContractVorm.Bestek:
            case RawContractVorm.Raamovereenkomst:
                break;
            case RawContractVorm.Overeenkomst:
                // Bij jaarversie 2010 kan ook een Overeenkomst voorkomen
                if (jaarversie != RawJaarversie.v2010)
                {
                    logboek.Toevoegen(begroting._Naam, ProjectResources.TradA002412726923);
                }
                break;
            default:
                logboek.Toevoegen(begroting._Naam, ProjectResources.TradB);
                break;
        }

        // Voortijdig afbreken indien jaarversie en contractvorm nog niet bekend is
        if (logboek.Aantal > logAantal)
            return false;

        #endregion   // Controle van gegevens op begrotingsniveau

        #region Controle van de begrotingsregels

        #region Voorbereiding van de begrotingsregelcontrole

        // Deze regel bevat het subtotaal voor de staart.
        BOpslagpost? opslagPostSubtotaalVoorStaart = null;
        //Verplichte SubTotaal en Opslag Posten > % @
        Dictionary<string, string> verplichteOpslagPostenDirectNaPost = new Dictionary<string, string>();
        verplichteOpslagPostenDirectNaPost.Add(RawRegelgeving.c_RawStaartCode, BBegrotingsRegel.c_sStkSubBgr);
        verplichteOpslagPostenDirectNaPost.Add(RawRegelgeving.c_RawStaartCode96, BBegrotingsRegel.c_sStkSubBgr);

        //Verplichte Hoofdstukken
        Dictionary<string, string> verplichteHoofdstukken = new Dictionary<string, string>();
        if (jaarversie >= RawJaarversie.v2015)
        {
            verplichteHoofdstukken.Add(RawRegelgeving.c_RawUitvoeringsKostenCode, RawRegelgeving.c_RawStaartCode92);
            verplichteHoofdstukken.Add(RawRegelgeving.c_RawAKCode, RawRegelgeving.c_RawStaartCode93);
            verplichteHoofdstukken.Add(RawRegelgeving.c_RawWRCode, RawRegelgeving.c_RawStaartCode94);
        }

        //Verboden Hoofdstukken
        List<string> verbodenPostPatterns = new List<string>();
        if (contractVorm == RawContractVorm.Raamovereenkomst)
        {
            verbodenPostPatterns.Add("^95[0-9]{0,4}$");             // Alle 95 (stel)posten
        }
        if (jaarversie < RawJaarversie.v2015)
        {
            verbodenPostPatterns.Add("^9[2-4]$");                   // Alleen de indexposten 92, 93 en 94
        }

        RawRegelgeving rawRegelgeving = RawRegelgeving.GetRawRegelgeving(jaarversie, contractVorm);

        // Verplichte posten in RAW
        Dictionary<string, string> verplichtePosten = new Dictionary<string, string>();
        verplichtePosten.Add(rawRegelgeving.CodeStaartpostKorting, "Korting");                     // Omschrijving uit 1.6 RAWSXDLX.xsd
        verplichtePosten.Add(RawRegelgeving.c_RawUitvoeringsKostenCode, "Uitvoeringskosten");
        verplichtePosten.Add(RawRegelgeving.c_RawAKCode, "Algemene kosten");
        verplichtePosten.Add(RawRegelgeving.c_RawWRCode, "Winst en risico");
        if (contractVorm != RawContractVorm.Raamovereenkomst)
            verplichtePosten.Add(rawRegelgeving.CodeStaartpostOverigeEenmaligeKosten, "Overige eenmalige kosten");    // Omschrijving uit 1.6 RAWSXDLX.xsd

        // Controleer of de eenheid voldoet aan de vereiste van het xsd
        // <xs:simpleType name="eenheid">
        //   < xs:annotation >
        //     < xs:documentation > Eenheid </ xs:documentation >
        //   </ xs:annotation >
        //   < xs:restriction base = "xs:string" >
        //     < xs:pattern value = "[a-zA-Z1-9/]{0,4}" />
        //   </ xs:restriction >
        // </ xs:simpleType >
        // LET-OP: bij een raamovereenkomst is in de staart de eenheid fixed '%' dit staat niet in dit pattern
        string patternEenheid = "^[a-zA-Z1-9]{0,4}$";
        Regex regexEenheid = new Regex(patternEenheid);
        NumberFormatInfo nfi = (NumberFormatInfo)NumberFormatInfo.CurrentInfo.Clone();
        BAfgerondRekenen afRek = begroting._AfgerondRekenen;
        if (!afRek._THE)
            logboek.Toevoegen(begroting._Naam, ProjectResources.TradA002412726915);
        else if (afRek._THE && afRek._Niveau != 2)
            logboek.Toevoegen(begroting._Naam, ProjectResources.TradA002412726916);

        // Uitbreiding van bestaande controle op rekenmethodiek instelling #8837
        // Hoeveelheid op 2 decimalen.
        // Eenheidsprijs op 2 decimalen.
        // Totaalbedrag op 2 decimalen.
        // Maar ook moet de optie aan staan
        int aantalDecimalen = 2;
        if (!afRek._HvhAfronden)
        {
            logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726917, aantalDecimalen));
        }
        else
        {
            if (afRek._AtlDcmHvh != aantalDecimalen)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726918, afRek._AtlDcmHvh, aantalDecimalen));
        }

        if (!afRek._EnhPrsAfronden)
        {
            logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726919, aantalDecimalen));
        }
        else
        {
            if (afRek._AtlDcmEnhPrs != aantalDecimalen)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726920, afRek._AtlDcmEnhPrs, aantalDecimalen));
        }

        if (!afRek._TotAfronden)
        {
            logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726921, aantalDecimalen));
        }
        else
        {
            if (afRek._AtlDcmTot != aantalDecimalen)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradA002412726922, afRek._AtlDcmTot, aantalDecimalen));
        }
        #endregion  // Voorbereiding van de begrotingsregelcontrole

        #region Doorloop de begrotingsregels
        for (int stuIndex = 0; stuIndex < begroting._Stu._Aantal; stuIndex++)
        {
            BStructuurRegel stuRegel = begroting._Stu[stuIndex];
            if (stuRegel._Tpe == EOnderbouwing.Element)
            {
                #region Elementcontrole
                BElement? elt = stuRegel._Regel as BElement;
                if (elt != null)
                {
                    if (stuRegel._Niveau == 1 | stuRegel._Niveau == 2)
                    {
                        try
                        {
                            if (string.IsNullOrEmpty(elt._CclCde.Trim()))
                            {
                                logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB1);
                            }
                            else
                            {
                                //Code oplopend
                                double d = double.Parse(elt._CclCde.Trim().Insert(1, nfi.NumberDecimalSeparator));
                                if (code == -1.0)
                                {
                                }
                                else if (d < code)
                                {
                                    logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB2);
                                }
                                else if (d == code)
                                {
                                    if (begroting._Stu.GeefVorigSubElement(stuIndex, out int indexOud))
                                    {
                                        var el = begroting._Stu[indexOud]._Regel as BElement;
                                        if (el != null && (el._CclCde.Trim().Length == elt._CclCde.Trim().Length))
                                        {
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB2);
                                        }
                                    }
                                }
                                // Code is te groot ongeldige waarde
                                //else if (d > 9.6003)
                                //{
                                //    logboek.Toevoegen(begroting._Naam, stuIndex, "Code mag niet groter zijn dan 960030.");
                                //}
                                code = d;
                                //Code van juiste formaat
                                if (stuRegel._Niveau == 2 && !regex.Match(elt._CclCde.Trim()).Success || elt._CclCde.Trim().Length > 6)
                                    logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB3);
                            }
                        }
                        catch (Exception ex)
                        {
                            logger.LogExceptionWithMessage(ex);

                            //Code bestaat niet uit alleen cijfers...
                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB4);
                        }

                        // Mag de post/hoofdstuk voorkomen?
                        foreach (string verbodenPostPattern in verbodenPostPatterns)
                        {
                            Regex verbodenPostRegex = new Regex(verbodenPostPattern);
                            if (verbodenPostRegex.Match(elt._CclCde).Success)
                            {
                                logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB5, elt._CclCde));
                            }
                        }

                        // Controleer of de omschrijving voldoet aan de vereiste van het xsd
                        // <xs:simpleType name="gen.naamkort" final="restriction">
                        //   <xs:annotation>
                        //	   <xs:documentation>Naam van 50 alfanumerieke posities</xs:documentation>
                        //   </xs:annotation>
                        //   <xs:restriction base="xs:normalizedString">
                        //     <xs:minLength value="1"/>
                        //     <xs:maxLength value="50"/>
                        //   </xs:restriction>
                        // </xs:simpleType>
                        if (elt._Oms.Length < 1)
                        {
                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB6);
                        }
                        else if (elt._Oms.Length > rawRegelgeving.MaxRomptekstLengte)
                        {
                            logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB7, rawRegelgeving.MaxRomptekstLengte.ToString()));
                        }

                        if (stuRegel._Niveau == 1)
                        {
                            //Hoofdstukken mogen niet onderbouwd zijn met Kostenposten.
                            if (begroting._Stu.GeefOnderliggendeKostenPosten(elt._Id).Count > 0 && jaarversie < RawJaarversie.v2015)
                                logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB8);
                            //Code 91 moet minimaal 1x voorkomen.
                            if (elt._CclCde.Trim() == RawRegelgeving.c_RawStaartCode91)
                                m_91 = true;
                            //Als het een begroting met begrotingsposten is dan waarschuwing geven als de hoeveelheid niet 1.0 is
                            if (begroting.BegrotingspostenToepassen && elt._Hvh != 1.0 && jaarversie < RawJaarversie.v2015)
                            {
                                logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradR0001); // R0001 Begrotingspost heeft geen hoeveelheid
                            }

                            // Als hoofdstuk96 aanwezig is, dan moeten er ook elementen met 96xxxx aanwezig zijn.
                            if (hoofdstuk96Aanwezig == false)
                            {
                                hoofdstuk96Aanwezig = elt._CclCde.Trim() == RawRegelgeving.c_RawStaartCode96;
                            }

                        }
                        else //niveau =2 => Bestekspost
                        {
                            // Lijst met verplichte posten controleren. Indien post gevonden, uit lijst verwijderen
                            if (verplichtePosten.ContainsKey(elt._CclCde))
                            {
                                if (elt._Oms != verplichtePosten[elt._CclCde])
                                {
                                    logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB9, elt._CclCde, verplichtePosten[elt._CclCde], elt._Oms));
                                }
                                verplichtePosten.Remove(elt._CclCde);
                            }

                            // Lijst met verplichte hoofdstukken controleren. Indien hoofdstuk gevonden, uit lijst verwijderen
                            if (verplichteHoofdstukken.ContainsKey(elt._CclCde))
                            {
                                IBegrotingsRegel hoofdstuk = begroting._Stu[stuIndex - 1]._Regel;
                                if (begroting._Stu[stuIndex - 1]._Niveau == 1 && hoofdstuk._CclCde == verplichteHoofdstukken[elt._CclCde])
                                {
                                    verplichteHoofdstukken.Remove(elt._CclCde);
                                }
                            }

                            if (RawBesteksPostNummer.NummerIsVolgpost(elt._CclCde))
                            {
                                logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB10, elt._CclCde));
                            }

                            if (RawBesteksPostNummer.NummerIsNulpost(elt._CclCde))
                            {
                                bool aardNietToegestaan = !rawRegelgeving.IsAardToegestaan(elt._CclCde.Trim(), elt._Postaard.Trim(), elt._Enh.Trim());
                                if (aardNietToegestaan)
                                {
                                    logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB11, elt._Postaard));
                                }

                                bool eenheidNietToegestaan;
                                // Controleer of de eenheid voldoet aan de vereiste van het xsd
                                if (contractVorm == RawContractVorm.Raamovereenkomst && RawBesteksPostNummer.NummerIsStaartpost(elt._CclCde))
                                {
                                    // LET OP: bij een raamovereenkomst is in de staart de eenheid fixed '%' dit staat niet in dit pattern
                                    eenheidNietToegestaan = elt._Enh != "%";
                                }
                                else
                                {
                                    eenheidNietToegestaan = !regexEenheid.Match(elt._Enh).Success;
                                }
                                if (eenheidNietToegestaan)
                                {
                                    logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB12, elt._Enh));
                                }

                                if (!eenheidNietToegestaan)
                                {
                                    // LET-OP: bij een raamovereenkomst moeten de bedragen uitgedrukt worden in op tienden afgeronde percentages
                                    if ((contractVorm == RawContractVorm.Raamovereenkomst) && RawBesteksPostNummer.NummerIsStaartpost(elt._CclCde) && (elt._Enh == "%"))
                                    {
                                        if (opslagPostSubtotaalVoorStaart != null)
                                        {
                                            if (!RawBesteksPostNummer.NummerIsBijdragepost(elt._CclCde))
                                            {
                                                double subTotaal = opslagPostSubtotaalVoorStaart.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out _);
                                                double percentage = elt.GeefDouble(BBegrotingsRegel.EGegeven.hvh, out _);
                                                // Controleer of het percentage op 1 decimaal nauwkeurig is
                                                decimal pct = (decimal)percentage / 100;
                                                if (pct != Math.Round(pct, 3))
                                                    logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB13, elt._CclCde));

                                                double elementTot = Math.Round(elt.GeefDouble(BBegrotingsRegel.EGegeven.drktot, out _), 2);
                                                double rawOkBedrag;
                                                double verschil;

                                                IBStatics statics = IoC.Resolve<IBStatics>();
                                                if (RawBesteksPostNummer.NummerIsKortingsPost(elt._CclCde, jaarversie))
                                                {
                                                    // Korting van een raamovereenkomst wordt berekend over posten die behoren tot de raamovereenkomst
                                                    // In alternatieve code staat de tekst 'behoort tot RO'
                                                    rawOkBedrag = Math.Round(begroting._RawInfo._RawAltSubtotaal * percentage / 100, 2);
                                                    verschil = Math.Round(rawOkBedrag - elementTot, 2);
                                                    if (!statics.IsNul(verschil))
                                                        logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB14, elt._CclCde, percentage, rawOkBedrag, verschil));
                                                }
                                                else
                                                {
                                                    rawOkBedrag = Math.Round(subTotaal * percentage / 100, 2);
                                                    verschil = Math.Round(rawOkBedrag - elementTot, 2);
                                                    if (!statics.IsNul(verschil))
                                                        logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB15, elt._CclCde, percentage, rawOkBedrag, verschil));
                                                }
                                            }
                                        }
                                    }
                                }

                                // Checken of het een bijdrage post betreft.
                                if (elt._CclCde.StartsWith(RawRegelgeving.c_RawStaartCode96))
                                {
                                    // Als element96 aanwezig is, dan moeten er ook hoofdstuk met 96 aanwezig zijn.
                                    if (!hoofdstuk96Aanwezig)
                                    {
                                        logboek.Toevoegen(begroting._Naam, stuIndex, string.Format(ProjectResources.TradB16, elt._CclCde, RawRegelgeving.c_RawStaartCode96));
                                    }

                                    // Als element96 aanwezig is, dan moeten er ook hoofdstuk met 96 aanwezig zijn.
                                    if (!elementen96Aanwezig)
                                    {
                                        elementen96Aanwezig = true;
                                    }
                                }

                            }

                            ERawBijzonderRegelType rawRegTpe = GeefRawRegelType(elt._CclCde.Trim(), jaarversie);
                            if (rawRegTpe != ERawBijzonderRegelType.Geen)
                            {
                                switch (rawRegTpe)
                                {
                                    case ERawBijzonderRegelType.Raw: //960010
                                        if ((RawTypes & (int)ERawBijzonderRegelType.Raw) == 0)
                                            RawTypes += (int)ERawBijzonderRegelType.Raw;
                                        else
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB17);
                                        break;
                                    case ERawBijzonderRegelType.Fco: //960020
                                        if ((RawTypes & (int)ERawBijzonderRegelType.Fco) == 0)
                                            RawTypes += (int)ERawBijzonderRegelType.Fco;
                                        else
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB18);
                                        break;
                                    case ERawBijzonderRegelType.Vsi: //960030
                                        if ((RawTypes & (int)ERawBijzonderRegelType.Vsi) == 0)
                                            RawTypes += (int)ERawBijzonderRegelType.Vsi;
                                        else
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB19);
                                        break;
                                    case ERawBijzonderRegelType.AK:  //939990
                                        if ((RawTypes & (int)ERawBijzonderRegelType.AK) == 0)
                                            RawTypes += (int)ERawBijzonderRegelType.AK;
                                        else
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB20);
                                        break;
                                    case ERawBijzonderRegelType.Winst: //949990
                                        if ((RawTypes & (int)ERawBijzonderRegelType.Winst) == 0)
                                            RawTypes += (int)ERawBijzonderRegelType.Winst;
                                        else
                                            logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB21);
                                        break;
                                    case ERawBijzonderRegelType.TotEenmaligeKosten: //919990
                                        logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB22);
                                        break;
                                }
                            }
                        }
                    }
                }
                #endregion  // Elementcontrole

            }
            else if (stuRegel._Tpe == EOnderbouwing.Kostenpost)
            {
                var ktp = stuRegel._Regel as BKostenpost;
                if (ktp != null &&
                    !String.IsNullOrEmpty(ktp._VzpId) &&
                    !BVerzamelpost.IsNetto(ktp._VzpId) &&
                    brutoVerzamelpostLetters.IndexOf(ktp._VzpId[0]) == -1)
                {
                    logboek.Toevoegen(begroting._Naam, stuIndex, ProjectResources.TradB23 + ktp._VzpId + ProjectResources.TradB24);
                    brutoVerzamelpostLetters += ktp._VzpId[0];
                }
            }
            else if (stuRegel._Tpe == EOnderbouwing.Opslagpost)
            {
                #region Opslagpostcontrole
                if (stuRegel._Regel is BOpslagpost opslagPost)
                {
                    IBegrotingsRegel regel = begroting._Stu[stuIndex - 1]._Regel;
                    if (verplichteOpslagPostenDirectNaPost.ContainsKey(regel._CclCde))
                    {
                        string verwachteStuurcode = verplichteOpslagPostenDirectNaPost[regel._CclCde];
                        if (verwachteStuurcode != null)
                        {
                            if (opslagPost.GeefString(BBegrotingsRegel.EGegeven.stk, false) == verwachteStuurcode)
                            {
                                // Verplichte OpslagPost gevonden. haal hem uit de lijst.
                                verplichteOpslagPostenDirectNaPost.Remove(regel._CclCde);
                                // Is de regel voor de opslagpost de indexpost '9' dan is dit de opslagPostSubtotaalVoorStaart
                                if (regel._CclCde == RawRegelgeving.c_RawStaartCode)
                                    opslagPostSubtotaalVoorStaart = opslagPost;
                            }
                        }
                    }
                    else
                    {
                        if (regel._CclCde.StartsWith(RawRegelgeving.c_RawStaartCode96) &&
                            verplichteOpslagPostenDirectNaPost.ContainsKey(RawRegelgeving.c_RawStaartCode96))
                        {
                            // Checken of de post een geldige stuurcode heeft.
                            if (opslagPost.GeefString(BBegrotingsRegel.EGegeven.stk, false) != "@")
                            {
                                verplichteOpslagPostenDirectNaPost.Add(regel._CclCde, BBegrotingsRegel.c_sStkEindOpslag);
                            }
                        }
                    }

                    /*Er moeten logmeldingen komen bij afdrukken ISS in een RAW 2015 RO 
                    als voor de posten KORTING, UK, AK en W&R een percentage is ingevoerd 
                    dan niet op tienden van procenten in ingegeven.*/
                    if (opslagPost._IsSubtotaalOpslag && contractVorm == RawContractVorm.Raamovereenkomst)
                    {
                        string postcode = regel._CclCde;
                        if (RawFuncties.NummerIsPercentagePost(postcode, jaarversie))
                        {
                            decimal pct = (decimal)opslagPost.GeefPercentages()[EKst.Aks];
                            if (pct != Math.Round(pct, 3))
                            {
                                // De percentages voor 'Korting', 'Uitvoeringskosten', 'Algemene kosten' en 'Winst en risico moeten worden afgerond op ééntiende
                                string naam = string.Empty;
                                if (RawBesteksPostNummer.NummerIsKortingsPost(postcode, jaarversie))
                                    naam = "Korting";
                                else if (RawBesteksPostNummer.NummerIsUitvoeringsKostenPost(postcode))
                                    naam = "Uitvoeringskosten";
                                else if (RawBesteksPostNummer.NummerIsAlgemeneKostenPost(postcode))
                                    naam = "Algemene kosten";
                                else if (RawBesteksPostNummer.NummerIsWinstEnRisicoPost(postcode))
                                    naam = "Winst en risico";

                                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB241, naam));
                            }
                        }
                    }
                }
                #endregion  // Opslagpostcontrole
            }
        }
        #endregion  // Doorloop de begrotingsregels

        #region Afhandeling van de begrotingsregelcontrole
        //Kijk of alle verplichte posten aanwzig zijn
        if (verplichtePosten.Any())
        {
            foreach (string calculatieCode in verplichtePosten.Keys)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB242, calculatieCode, verplichtePosten[calculatieCode]));
        }

        // Kijk of alle verplichte opslagposten aanwezig zijn
        if (verplichteOpslagPostenDirectNaPost.Any())
        {
            // LET OP! er kan nog steeds een geldige situatie zijn, als er helemaal geen bijdrage posten zijn, is het een geldig bestand.
            if (verplichteOpslagPostenDirectNaPost.ContainsKey(RawRegelgeving.c_RawStaartCode96) && verplichteOpslagPostenDirectNaPost.Count == 1)
            {
                // Verplichte OpslagPost gevonden. haal hem uit de lijst.
                verplichteOpslagPostenDirectNaPost.Remove(RawRegelgeving.c_RawStaartCode96);
            }

            foreach (string calculatieCode in verplichteOpslagPostenDirectNaPost.Keys)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB243, calculatieCode, verplichteOpslagPostenDirectNaPost[calculatieCode]));

        }

        if (hoofdstuk96Aanwezig && !elementen96Aanwezig)
        {
            logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB244, RawRegelgeving.c_RawStaartCode96));
        }

        // Kijk of alle verplichte index regels aanwezig zijn
        if (verplichteHoofdstukken.Any())
        {
            foreach (string calculatieCode in verplichteHoofdstukken.Keys)
                logboek.Toevoegen(begroting._Naam, string.Format(ProjectResources.TradB245, calculatieCode, verplichteHoofdstukken[calculatieCode]));
        }

        if (parentid != -1 && jaarversie < RawJaarversie.v2015)
        {
            var parentElt = begroting._Stu.GeefBegrotingsRegel(parentid) as BElement;
            if (parentElt != null && !parentElt._CclCde.StartsWith(RawRegelgeving.c_RawStaartCode91))
                logboek.Toevoegen(begroting._Naam, ProjectResources.TradB246);
        }
        if (!m_91)
            logboek.Toevoegen(begroting._Naam, ProjectResources.TradB247);

        #endregion Afhandeling van de begrotingsregelcontrole

        #endregion  // Controle van de begrotingsregels

        #region Controle van het begrotingblad
        logboek.ContextView = EViewKey.BBldGridInBegrotingbladView;

        BBgrBladTabel bgrBladTabel = begroting.GeefBgrBladTabel();
        int aantalRijen = bgrBladTabel.AantalRijen();
        for (int rijNr = 0; rijNr < aantalRijen; rijNr++)
        {
            BBgrBladRegel bgrBladRegel = bgrBladTabel._Lijst[rijNr];
            if (bgrBladRegel._RegelSoort == BBgrBladRegel.EBbdRegelSoort.Functie)
            {
                BBegrotingBladFunctie? functie = bgrBladRegel._Functie;
                switch (functie._FunctieSoort)
                {
                    case BBegrotingBladFunctie.EFunctieSoort.Commentaar:
                    case BBegrotingBladFunctie.EFunctieSoort.Eenheidsprijs:
                    case BBegrotingBladFunctie.EFunctieSoort.SectieTotaal:
                    case BBegrotingBladFunctie.EFunctieSoort.Totaal:
                    case BBegrotingBladFunctie.EFunctieSoort.TussenTotaal:
                    case BBegrotingBladFunctie.EFunctieSoort.Verzamelpost:
                    case BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwGeen:
                    case BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwHoog:
                    case BBegrotingBladFunctie.EFunctieSoort.GrondslagBtwLaag:
                        // Deze functiesoorten zijn toegestaan op een begrotingsblad van een RAW-begroting
                        break;

                    default:
                        logboek.Toevoegen(begroting._Naam, rijNr + 1, ProjectResources.TradB249);
                        break;
                }
            }
        }
        if (aantalRijen == 0 ||
            bgrBladTabel._Lijst[aantalRijen - 1]._RegelSoort != BBgrBladRegel.EBbdRegelSoort.Functie ||
            bgrBladTabel._Lijst[aantalRijen - 1]._Functie._FunctieSoort != BBegrotingBladFunctie.EFunctieSoort.Totaal)
        {
            logboek.Toevoegen(begroting._Naam, aantalRijen, ProjectResources.TradB2410);
        }
        #endregion  // Controle van het begrotingblad

        if (logboek.Aantal > logAantal)
            return false;

        return true;
    }

    public string? VolgendeDocumentTekstRegel(ETekstType tekstType)
    {
        string? waarde = null;
        string tekst = string.Empty;

        switch (tekstType)
        {
            case ETekstType.Voorblad: tekst = m_RawVoorblad; break;
            case ETekstType.Inschrijfbiljet: tekst = m_RawInschrijfBiljet; break;
        }
        if (!string.IsNullOrEmpty(tekst) && m_Offset < tekst.Length)
        {
            int crlf = tekst.IndexOf(Environment.NewLine, m_Offset);
            if (crlf < 0)
                crlf = tekst.Length;

            waarde = tekst.Substring(m_Offset, crlf - m_Offset);
            m_Offset = crlf + Environment.NewLine.Length;
        }
        return waarde;
    }
    /// <summary>Wijzig de rawstatus van wel Raw naar geen Raw of omgekeerd
    /// </summary>
    /// <param name="status"></param>
    public void ZetRawBegroting(bool isRawBegroting)
    {
