        // 3. Ga op zoek naar de volgende [variabele]
        if (!string.IsNullOrEmpty(tekst)) // Is er wel tekst?
        {
            int openPos = tekst.IndexOf('[');  // Zoek naar het begin van [variabele]
            while (openPos >= 0)  // Zolang er een rechte haak openen is gevonden
            {
                int sluitPos = tekst.IndexOf(']', openPos + 1); // Zoek de bijbehorende rechte haak sluiten
                if (sluitPos < 0)  // Niet gevonden?
                    break; // Niets meer vervangen

                string variabele = tekst.Substring(openPos + 1, sluitPos - openPos - 1);
                string waarde = GeefBegrotingsGegeven(variabele); // Zoek de waarde van de variable op
                if (!string.IsNullOrEmpty(waarde)) // Waarde van de variabele gevonden?
                {
                    if (variabele == variabele.ToLower()) // Kleine letters gewenst?
                        waarde = waarde.ToLower();
                    else if (variabele == variabele.ToUpper()) // Hoofdletters gewenst?
                        waarde = waarde.ToUpper();
                    tekst = tekst.Substring(0, openPos) + waarde + tekst.Substring(sluitPos + 1); // De substitutie zelf
                }
                openPos = tekst.IndexOf('[', openPos + 1);  // Zoek de volgende rechte haak openen
            }
        }
    }

