    /// <summary>
    /// Wijzig de double-waarde van een veld
    /// </summary>
    /// <param name="kolomNr">Nummer van de kolom</param>
    /// <param name="rijNr">Nummer van de rij</param>
    /// <param name="waarde">Waarde van het veld</param>
    /// <returns>true indien de nieuwe waarde verschilt van de oude, de wijziging is niet lokaal</returns>
    public bool VeldDouble(int kolomNr, int rijNr, double waarde)
    {
        int stuIndex = StuIndex(rijNr);
        if (AlleenLezen())
        {
            m_Structuur[stuIndex]._Regel.VerversUi();
            return true;
        }

        BOpdracht? opdracht;
        BStructuurRegel structuurRegel = m_Structuur.LeesBegrotingsRegel(stuIndex);
        bool moetVerversen = true;
        switch ((EGegeven)kolomNr)
        {
            case BBegrotingsRegel.EGegeven.hvh:
                bool nieuweGroepeerOpdrachtGemaakt = false;
                try
                {
                    nieuweGroepeerOpdrachtGemaakt = m_Begroting.GroepeerOpdrachten();
                    // Als WijzigDoubleBgrRegel != null geeft dan is er iets gewijzigd >> dan ook de meting verbreken
                    if ((opdracht = m_Begroting.WijzigDoubleBgrRegel(stuIndex, (EGegeven)kolomNr, waarde, false)) != null)
                    {
                        if (structuurRegel._Regel.HeeftBim2D3DMeting)
                        {
                            int oid = structuurRegel._Regel.GeefInteger(BBegrotingsRegel.EGegeven.oid);
                            if (oid > 0)
                            {
                                m_Begroting.WijzigIntegerBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.oid, -oid);
                            }
                        }
                        else
                        {
                            m_Begroting.WijzigIntegerBgrRegel(stuIndex, BBegrotingsRegel.EGegeven.oid, 0);
                        }
                    }
                }

                finally
                {
                    if (nieuweGroepeerOpdrachtGemaakt) opdracht = m_Begroting.GroepeerOpdrachten(m_ViewNr, "Wijzig hoeveelheid");
                }
                break;

            default:
                opdracht = m_Begroting.WijzigDoubleBgrRegel(stuIndex, (EGegeven)kolomNr, waarde, false);
                break;
        }

        if (opdracht == null)  // Wijziging is niet uitgevoerd
            m_Structuur[stuIndex]._Regel.VerversUi();   // Deze regel moet ververst worden om de oude waarde weer te voorschijn te toveren
        else
            opdracht.SetView(m_ViewNr);

        return moetVerversen;
    }

    /// <summary>
    /// Wijzig de tekst-waarde van een veld
    /// </summary>
    /// <param name="kolomNr">Nummer van de kolom</param>
    /// <param name="rijNr">Nummer van de rij</param>
