    /// <summary>
    /// Activeer voor elke rij die gewijzigd is de callback-functie(s)
    /// </summary>
    /// <param name="dlgte">De callback-functie</param>
    public void GewijzigdeRijen(GewijzigdeRijDlgte dlgte, ref int viewVersie)
    {
        bool isGewijzigd = false;
        int stuIndex = -1;
        int aantalRegels = m_Structuur._Aantal;

        _voortgangsBalk.ZetAantalenMsg(0, aantalRegels, "Verversen", false, 0);

        while (m_Structuur.GeefGewijzigdeRegel(ref stuIndex, viewVersie))
        {
            _voortgangsBalk.Perc(aantalRegels - stuIndex);

            // Indien er een filter is toegepast dan is het mogelijk dat de
            // gewijzigde regel wordt weggefilterd.
            // Indien er geen filter is toegepast dan wordt alleen het rootelement overgeslagen.
            int rijNr = stuIndex - 1;
            if (rijNr >= 0)
                dlgte(rijNr);
            isGewijzigd = true;
        }

        if (isGewijzigd)
            m_Begroting.UiVerverst(ref viewVersie);
        _voortgangsBalk.ZetVoortgangsBalkOpNul();
        _bucStatusbar.StatusbarMsg(string.Empty);
    }

