    /// <summary>
    /// Geef het soort rij (bijv. stuurkode) van een rij.
    /// Nul indien niet van toepassing.
    /// </summary>
    /// <param name="rijNr">Nummer van de rij</param>
    /// <returns>Stuurkode o.i.d.</returns>
    public char RijSoort(int rijNr)
    {
        Debug.Assert(rijNr == -1 || (rijNr >= 0 && rijNr < AantalRijen()), "Verkeerde index");
        int stuIndex = StuIndex(rijNr);

        switch (m_Structuur[stuIndex]._Tpe)
        {
            case EOnderbouwing.Commentaar:
                return 'C';

            case EOnderbouwing.Element:
                {
                    int niveau = m_Structuur.GeefNiveau(stuIndex);
                    if (niveau == 1)   // hoofdstuk
                        return 'H';
                    if (niveau == 2)   // subhoofdstuk
                        return 'S';
                    if (niveau == 3)   // paragraaf
                        return 'P';
                    return 'E';       // element van nog hoger niveau
                }

            case EOnderbouwing.Kostenpost:
                //return 'K';
                // toekomst: losse kostenpost onderscheiden
                {
                    int niveau = m_Structuur.GeefNiveau(stuIndex);
                    return (niveau == 1) ? 'L' : 'K';
                }

            case EOnderbouwing.Opslagpost:
                return 'O';

            default:
                throw new OnbekendOnderbouwingstypeException();
                // break;  unreachable
        }
        // return ' ';  unreachable
    }
