    public string? GeefValutaTeken(int tabelKolomNr, int rijNr)
    {
        IBegrotingsRegel? bgrRegel = GeefBegrotingsRegel(rijNr);
        if (bgrRegel is BKostenpost kostenpost && HeeftMogelijkAfwijkendeValuta(tabelKolomNr))
            return kostenpost.GeefValutateken(basisValutaAlsLegeTekst: false);

        return null;

        static bool HeeftMogelijkAfwijkendeValuta(int tabelKolomNr)
        {
            return tabelKolomNr >= (int)EGegeven.ntoarb && tabelKolomNr <= (int)EGegeven.ntoaks ||
                   tabelKolomNr >= (int)EGegeven.prsmta && tabelKolomNr <= (int)EGegeven.prsoda ||
                   tabelKolomNr == (int)EGegeven.ulnbdr;
        }
    }

    /// <summary>
    /// Geef de tekst-waarde van een veld
    /// </summary>
    /// <param name="kolomNr">Nummer van de kolom</param>
    /// <param name="rijNr">Nummer van de rij</param>
    /// <returns>Waarde van het veld</returns>
    public string VeldString(int kolomNr, int rijNr)
    {
        BStructuurRegel stuRegel = Veld_GeefStructuurRegel(rijNr);
        if (stuRegel._Regel == null)
            return string.Empty;

        if (kolomNr < BTabelOpmaak.c_EersteVerschilTabelKolomNr)
        {
            if (stuRegel.IsElement && 
                (kolomNr == (int)EGegeven.stk || kolomNr == (int)EGegeven.postaard))
            {
                int niveau = stuRegel._Niveau;
                if (niveau == -1)
                    niveau = m_Structuur.GeefNiveau(StuIndex(rijNr));
                BElement element = (BElement)stuRegel._Regel;
                if (kolomNr == (int)EGegeven.stk)
                    return element.GeefNiveauIndicatie(niveau);

                Debug.Assert(kolomNr == (int)EGegeven.postaard, "VeldString() - geen stk en geen postaard");
                return element.GeefPostaard(niveau);
            }
            else if (stuRegel.IsKostenpost && (EGegeven)kolomNr == EGegeven.vltteken &&
                kostenpostHeeftBasisvaluta((BKostenpost)stuRegel._Regel))
            {
                return string.Empty;
            }

            return stuRegel._Regel.GeefString((EGegeven)kolomNr, true);
        }
        return ReferentieVeldString(stuRegel._Regel, kolomNr);

        bool kostenpostHeeftBasisvaluta(BKostenpost kostenpost) => _Begroting._BasisValuta._VltId == kostenpost._Middel._VltId;
     }
