    public BOpdracht? KopieerRegelIntern(int bronRijNr, int doelRijNr, bool rijToevoegen, bool navigatiemode)
    {
        int bronIndex = StuIndex(bronRijNr);
        int doelIndex = StuIndex(doelRijNr);

        IBegrotingsRegel? bgrreg = GeefBegrotingsRegel(bronRijNr);
        if (bgrreg is BKostenpost)
        {
            //kijk naar de instelling van F9
            bool RegelBijBoven = _functionsConfiguration.AddNewLineAboveCurrent.Value ?? false;
            if (!RegelBijBoven) doelIndex++; // nieuwe regel moet eronder
        }
        KopieerBegrotingRegelInternOpdracht opdracht = new KopieerBegrotingRegelInternOpdracht(m_Begroting, bronIndex, doelIndex /* ,true */ , navigatiemode);
        opdracht.SetView(m_ViewNr);
        opdracht._RegelNummer = doelIndex;
        _Begroting._Context = opdracht._Context;

        if (!opdracht.Uitvoeren(_Begroting))
            return null;
        return opdracht;
    }
