    /// <summary>
    /// Geef het nummer van de kolom waarin voor een bepaalde (of alle) rijsoort(-en) een bijzonderheid geldt
    /// </summary>
    /// <param name="bijzonderheid">Omschrijving van de specialiteit van de kolom</param>
    /// <param name="specificatie">Specificatie-object, of null bv BOpmaakRijSoort,int,...</param>
    /// <returns>Nummer van de kolom</returns>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Performance", "CA1800:DoNotCastUnnecessarily")]
    public int BijzondereKolom(string bijzonderheid, object? specificatie)
    {
        if (bijzonderheid == BApplicatie.c_BijzklmUitsmeerbaar)            // Kolom met tekst die uitgesmeerd kan worden over andere kolommen
            return BijzklmUitsmeerbaar(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmInspringen)              // Kolom waarvan de tekst inspringt
            return BijzklmInspringen(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmInitialiseren || bijzonderheid == BApplicatie.c_BijzklmControlecode)   // Kolom waarvan de waarden tot een speciale set van waarden moeten behoren. De kolom is wel wijzigbaar maar niet vrij wijzigbaar, niet elke waarde kan worden geaccepteerd.
            return BijzklmInitialiserenBijzklmControlecode(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmStuurcode)
            return BijzklmStuurcode(specificatie);
        if (bijzonderheid == BApplicatie.c_BijzklmKopieer)
            return BijzklmKopieer(specificatie);
        return -1;
    }
    private static int BijzklmUitsmeerbaar(object? specificatie)
    {
        BOpmaakRijSoort? rs = specificatie as BOpmaakRijSoort;

        if (rs?._RijSoort == 'C')                          // Commentaarregel
            return (int)EGegeven.oms;    // Omschrijvingkolom
        return -1;
    }
    private static int BijzklmInspringen(object? specificatie)
    {
        Debug.Assert(specificatie is int, "BBegrotingUi.BijzondereKolom Specificatie argument is geen int ");

        int tabelkolomnr = (int)specificatie;
        if (tabelkolomnr == (int)EGegeven.cclcde ||
           tabelkolomnr == (int)EGegeven.oms ||
           tabelkolomnr == (int)EGegeven.loccde)
            return tabelkolomnr;
        return -1;
    }

    private static int BijzklmInitialiserenBijzklmControlecode(object? specificatie)
    {
        Debug.Assert(specificatie is int, "BBegrotingUi.BijzondereKolom Specificatie argument is geen int ");
        int tabelkolomnr = (int)specificatie;
        if (tabelkolomnr == (int)EGegeven.ulnbdr)
