    private static int BijzklmStuurcode(object? specificatie)
    {
        Debug.Assert(specificatie is string, "BBegrotingUi.BijzondereKolom Specificatie argument is geen string ");

        var stuurcode = (specificatie as string)?.Trim();
        if (stuurcode != null && stuurcode.Length > 0)
        {
            // returnwaarde
            // -1 = Geen controle uitgevoerd (niet nodig) 
            //  0 = Controle uitgevoerd, resultaat "false"
            //  1 = Controle uitgevoerd, resultaat "true"
            if (c_sAlleStuurcodes.Contains(stuurcode))
