    /// <summary>Onthouden van de laatst opgezochte referentie stu index. Vaak worden de achtereenvolgende gegevens van
    /// eenzelfde referentieregel opgevraagd
    /// </summary>
    protected int m_ReferentieRegelStuIndex = -1;

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// Bij tabelkolomnummer "VerschilTabelKolomNr" wordt het verschil tussen begrotin en referentie gegeven
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders 0.0 (geenWaarde is dan true)</returns>
    private double ReferentieVeldDouble(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;

        if (m_VerschilMode == EVerschilMode.Elementen && bgrRegel._OnderbouwingType == EOnderbouwing.Kostenpost)
        {
            geenWaarde = true;
            return 0.0;
        }
        double waarde = 0.0;

        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);

        if (refRegel != null)
        {
            if (kolomNr != BTabelOpmaak.c_VerschilTabelKolomNr)
            {
                waarde = refRegel.GeefDouble((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr), out geenWaarde);
            }
            else
            {
                double bgrTotaal = bgrRegel.GeefDouble(BBegrotingsRegel.EGegeven.btoaks, out geenWaarde);
                if (!geenWaarde)
                {
                    double refTotaal = refRegel.GeefDouble(BBegrotingsRegel.EGegeven.btoaks, out geenWaarde);
                    waarde = refTotaal - bgrTotaal;
                }
            }
        }
        return waarde;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders 0 (geenWaarde is dan true)</returns>
    private int ReferentieVeldInteger(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
            return refRegel.GeefInteger((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr));

        geenWaarde = true;
        return 0;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <param name="geenWaarde">Indicatie geen waarde aanwezig</param>
    /// <returns>De gevonden waarde anders DateTime.now (geenWaarde is dan true)</returns>
    private DateTime ReferentieVeldDatum(IBegrotingsRegel bgrRegel, int kolomNr, out bool geenWaarde)
    {
        geenWaarde = false;
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
            return refRegel.GeefDatum((EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr), out geenWaarde);

        geenWaarde = true;
        return DateTime.Now;
    }

    /// <summary>Haal de overeenkomstige waarde van een opgegeven kolom uit de referentie "Prijzen"
    /// De waarde wordt opgezocht op basis van overeenkomende code
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <param name="kolomNr">Het gevraagde gegeven (tabelkolomnummer)</param>
    /// <returns>De gevonden waarde anders string.Empty</returns>
    private string ReferentieVeldString(IBegrotingsRegel bgrRegel, int kolomNr)
    {
        IBegrotingsRegel? refRegel = GeefReferentieRegel(bgrRegel);
        if (refRegel != null)
        {
            var gegeven = (EGegeven)(kolomNr - BTabelOpmaak.c_EersteVerschilTabelKolomNr);
            if(gegeven == EGegeven.stk && refRegel is BElement element)
                return GeefReferentieElementStuurcode(element);

            return refRegel.GeefString(gegeven, true);
        }

        return string.Empty;
    }

    /// <summary>Zoek een regel in de referentie op basis van de code van een opgegeven regel
    /// </summary>
    /// <param name="bgrRegel">De originele begrotingsregel</param>
    /// <returns>De gevonden regel en anders null</returns>
    private IBegrotingsRegel? GeefReferentieRegel(IBegrotingsRegel bgrRegel)
    {
        if (string.IsNullOrEmpty(bgrRegel._CclCde))
            return null;

        IBegroting? prijzenBoek = m_Begroting._PrijzenBoek;
        if (prijzenBoek == null)
            return null;

        IStructuur prijzenboekStu = prijzenBoek._Stu;

        if (m_ReferentieRegelStuIndex > 0)
        {
            BStructuurRegel stuRegel = prijzenboekStu.LeesBegrotingsRegel(m_ReferentieRegelStuIndex);
            if (stuRegel._Regel._CclCde == bgrRegel._CclCde)
                return stuRegel._Regel;
        }

        for (int stuIndex = 0; stuIndex < prijzenboekStu._Aantal; stuIndex++)
        {
            BStructuurRegel stuRegel = prijzenboekStu.LeesBegrotingsRegel(stuIndex);
            if (stuRegel._Regel._CclCde == bgrRegel._CclCde)
            {
                m_ReferentieRegelStuIndex = stuIndex;
                return stuRegel._Regel;
            }
        }

        return null;
    }

    private string GeefReferentieElementStuurcode(BElement element)
    {
        const string DefaultStuurcode = "+";
        if (m_ReferentieRegelStuIndex <= 0) return DefaultStuurcode;
        
        IBegroting? prijzenBoek = m_Begroting._PrijzenBoek;
        if (prijzenBoek == null) return DefaultStuurcode;

        var prijzenboekStructuur = prijzenBoek._Stu;
        var referentieRegel = prijzenboekStructuur[m_ReferentieRegelStuIndex];
        var niveau = referentieRegel._Niveau;
        if(niveau < 1)
            niveau = prijzenboekStructuur.GeefNiveau(m_ReferentieRegelStuIndex);

        return element.GeefNiveauIndicatie(niveau);
    }

